begin;
insert into auth.users(id,email) select ('01000000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid,'author-fixture'||n||'@example.invalid' from generate_series(1,4)n;
insert into auth.sessions(id,user_id) select ('11000000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid,('01000000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid from generate_series(1,4)n;
insert into public.profiles(id,organization_id,username,full_name,role) select ('01000000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid,'6e143c55-7be5-4e6e-9f1a-8f8db429956a','author_fixture_'||n,'Author test',case n when 1 then 'admin' when 2 then 'teacher' when 3 then 'student' else 'teacher' end from generate_series(1,4)n;
insert into public.classes(id,organization_id,name) values('31000000-0000-4000-8000-000000000001','6e143c55-7be5-4e6e-9f1a-8f8db429956a','Author test class');
insert into public.subjects(id,organization_id,name) values('41000000-0000-4000-8000-000000000001','6e143c55-7be5-4e6e-9f1a-8f8db429956a','Author test subject');
insert into public.teacher_assignments(organization_id,teacher_id,class_id,subject_id) values('6e143c55-7be5-4e6e-9f1a-8f8db429956a','01000000-0000-4000-8000-000000000002','31000000-0000-4000-8000-000000000001','41000000-0000-4000-8000-000000000001');
create function pg_temp.check_it(ok boolean,label text) returns void language plpgsql as $$begin if ok is distinct from true then raise exception 'FAIL %',label;end if;end$$;
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"01000000-0000-4000-8000-000000000001","session_id":"11000000-0000-4000-8000-000000000001","role":"authenticated"}',true);
do $test$ declare e uuid; q uuid; result jsonb; v jsonb; req uuid:=gen_random_uuid(); input jsonb; caught boolean; before_version int; begin
 result:=public.authoring_command(jsonb_build_object('action','exam','exam',jsonb_build_object('title','Author test exam','subject_id','41000000-0000-4000-8000-000000000001','class_ids',jsonb_build_array('31000000-0000-4000-8000-000000000001'),'starts_at',now()+interval '1 day','ends_at',now()+interval '2 day','duration_minutes',60,'pin','778899','passing_grade',60,'status','scheduled','bypass_period',false,'shuffle_questions',true,'shuffle_options',true,'configs',(select jsonb_agg(jsonb_build_object('type',t,'enabled',true,'max_questions',case when t='PG' then 1 else 0 end,'option_count',2,'default_points',1)) from unnest(array['PG','PG_KOMPLEKS','BS','JODOH','Esai'])t))));
 e:=(result->>'id')::uuid;
 perform set_config('test.exam',e::text,true);
 v:='{"type":"PG","stem":"First","points":1,"required":true,"options":[{"id":"A","text":"One"},{"id":"B","text":"Two"}],"key":["A"],"explanation":"","rubric":"","minChars":0,"direction":"ltr","attachments":[],"canvas":{"enabled":false,"width":1000,"height":600}}'::jsonb;
 input:=jsonb_build_object('action','questions','exam_id',e,'request_id',req,'items',jsonb_build_array(v));
 result:=public.authoring_command(input);perform pg_temp.check_it((result->>'saved')::int=1,'first insert');q:=(result->'details'->0->>'id')::uuid;
 perform pg_temp.check_it(public.authoring_command(input)=result,'idempotent replay');
 result:=public.authoring_command(jsonb_build_object('action','questions','exam_id',e,'request_id',gen_random_uuid(),'items',jsonb_build_array(jsonb_set(v,'{stem}','"Second"'))));perform pg_temp.check_it(result->'details'->0->>'error'='QUOTA','quota boundary');
 result:=public.authoring_command(jsonb_build_object('action','questions','exam_id',e,'question_id',q,'expected_version',1,'request_id',gen_random_uuid(),'items',jsonb_build_array(jsonb_set(v,'{stem}','"Edited"'))));perform pg_temp.check_it((result->>'saved')::int=1,'edit creates version');
 perform pg_temp.check_it((select count(*) from public.question_versions where question_id=q)=2,'history retained');
 result:=public.authoring_command(jsonb_build_object('action','questions','exam_id',e,'question_id',q,'expected_version',1,'request_id',gen_random_uuid(),'items',jsonb_build_array(v)));perform pg_temp.check_it(result->'details'->0->>'error' like 'CONFLICT:%','stale edit');
 result:=public.authoring_command(jsonb_build_object('action','questions','exam_id',e,'request_id',gen_random_uuid(),'items',jsonb_build_array(jsonb_set(v,'{stem}','"<img src=x onerror=evil()>"'))));perform pg_temp.check_it(result->'details'->0->>'error' like 'HTML%','direct RPC HTML rejected');
 caught:=false;begin perform public.authoring_command(jsonb_build_object('action','questions','exam_id',e,'request_id',gen_random_uuid(),'items',(select jsonb_agg(v) from generate_series(1,501))));exception when others then caught:=true;end;perform pg_temp.check_it(caught,'501 rejected');
 result:=public.authoring_command(jsonb_build_object('action','questions','exam_id',e,'request_id',gen_random_uuid(),'items',(select jsonb_agg(v) from generate_series(1,500))));perform pg_temp.check_it(jsonb_array_length(result->'details')=500,'500 handled');

 -- Unlimited quota still accepts distinct questions, and all five types validate in DB.
 result:=public.authoring_command(jsonb_build_object('action','questions','exam_id',e,'request_id',gen_random_uuid(),'items',jsonb_build_array(jsonb_set(v,'{type}','"PG_KOMPLEKS"'))));perform pg_temp.check_it((result->>'saved')::int=1,'PG complex');
 result:=public.authoring_command(jsonb_build_object('action','questions','exam_id',e,'request_id',gen_random_uuid(),'items',jsonb_build_array(jsonb_set(jsonb_set(v,'{type}','"BS"'),'{key}','["true","false"]'))));perform pg_temp.check_it((result->>'saved')::int=1,'BS');
 result:=public.authoring_command(jsonb_build_object('action','questions','exam_id',e,'request_id',gen_random_uuid(),'items',jsonb_build_array(jsonb_set(jsonb_set(v,'{type}','"JODOH"'),'{key}','["Answer one","Answer two"]'))));perform pg_temp.check_it((result->>'saved')::int=1,'JODOH');
 v:=jsonb_set(jsonb_set(jsonb_set(v,'{type}','"Esai"'),'{options}','[]'),'{key}','[]');
 result:=public.authoring_command(jsonb_build_object('action','questions','exam_id',e,'request_id',gen_random_uuid(),'items',(select jsonb_agg(jsonb_set(v,'{stem}',to_jsonb('Essay number '||n))) from generate_series(1,500)n)));
 perform pg_temp.check_it((result->>'saved')::int=500,'500 distinct essays saved with max zero unlimited');
 result:=public.authoring_command(jsonb_build_object('action','duplicate_exam','exam_id',e,'pin','998877'));before_version:=0;
 input:=jsonb_build_object('action','copy','exam_id',result->>'id','source_exam_id',e,'request_id',gen_random_uuid(),'ids',jsonb_build_array(q));
 result:=public.authoring_command(input);perform pg_temp.check_it((result->>'saved')::int=1 and result->'details'->0->>'id'<>q::text,'copy new question ID');
 perform public.authoring_command(jsonb_build_object('action','period','enabled',true,'starts_at',now()-interval '2 day','ends_at',now()-interval '1 day'));
end $test$;
select set_config('request.jwt.claims','{"sub":"01000000-0000-4000-8000-000000000002","session_id":"11000000-0000-4000-8000-000000000002","role":"authenticated"}',true);
select pg_temp.check_it(exists(select 1 from public.exams where id=current_setting('test.exam')::uuid),'teacher scope');
do $$ declare denied boolean:=false;begin begin perform public.authoring_command(jsonb_build_object('action','archive_questions','exam_id',current_setting('test.exam'),'ids',jsonb_build_array(gen_random_uuid())));exception when others then denied:=sqlerrm like 'PERIOD:%';end;perform pg_temp.check_it(denied,'period server guard');end$$;
select set_config('request.jwt.claims','{"sub":"01000000-0000-4000-8000-000000000004","session_id":"11000000-0000-4000-8000-000000000004","role":"authenticated"}',true);
select pg_temp.check_it(not exists(select 1 from public.exams),'unassigned teacher denied');
select set_config('request.jwt.claims','{"sub":"01000000-0000-4000-8000-000000000003","session_id":"11000000-0000-4000-8000-000000000003","role":"authenticated"}',true);
select pg_temp.check_it(not exists(select 1 from public.question_versions),'student keys denied');
reset role;
update public.exams set status='closed' where id=current_setting('test.exam')::uuid;
select public.advance_exam_schedule();
select pg_temp.check_it((select status='closed' from public.exams where id=current_setting('test.exam')::uuid),'scheduler cannot reopen manual close');
update public.exams set status='scheduled',starts_at=now()-interval '1 hour' where id=current_setting('test.exam')::uuid;
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"01000000-0000-4000-8000-000000000001","session_id":"11000000-0000-4000-8000-000000000001","role":"authenticated"}',true);
do $$ declare denied boolean:=false;begin begin perform public.authoring_command(jsonb_build_object('action','archive_questions','exam_id',current_setting('test.exam'),'ids',jsonb_build_array(gen_random_uuid())));exception when others then denied:=sqlerrm like 'LOCKED:%';end;perform pg_temp.check_it(denied,'post-start lock');end$$;
rollback;
